const svg = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.decks}</svg>`;
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const store = {read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}},remove(key){try{localStorage.removeItem(key);return true;}catch{return false;}}};
const tcgCatalog = [
 {id:'lorcana',name:'Disney Lorcana',url:'https://www.disneylorcana.com/en-US/'},
 {id:'pokemon',name:'Pokémon TCG',url:'https://www.pokemon.com/us/pokemon-tcg/'},
 {id:'onepiece',name:'ONE PIECE CARD GAME',url:'https://en.onepiece-cardgame.com/'},
 {id:'magic',name:'Magic: The Gathering',url:'https://magic.wizards.com/en/intro'},
 {id:'yugioh',name:'Yu-Gi-Oh! TCG',url:'https://www.yugioh-card.com/en/'},
 {id:'digimon',name:'Digimon Card Game',url:'https://world.digimoncard.com/'},
 {id:'fab',name:'Flesh and Blood',url:'https://fabtcg.com/'},
 {id:'gundam',name:'GUNDAM CARD GAME',url:'https://www.gundam-gcg.com/asia-en/welcome/'},
 {id:'vanguard',name:'Cardfight!! Vanguard',url:'https://en.cf-vanguard.com/'},
 {id:'weiss',name:'Weiß Schwarz',url:'https://en.ws-tcg.com/'}
];
const profileKey='verso-player-preview-v1',profilesKey='verso-player-profiles-v2',sessionKey='verso-local-session-v1';
const profileBackgrounds=['aurora','midnight','sunset','mint','custom'];
function newLocalId(){if(crypto.randomUUID)return crypto.randomUUID();return 'local-'+Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');}
function normalizeProfile(value){
 if(!value||typeof value.name!=='string'||!value.name.trim()||!['hello','win','peek'].includes(value.mascot))return null;
 const legacy={Lorcana:'lorcana','Disney Lorcana':'lorcana','Pokémon':'pokemon','One Piece':'onepiece'};
 const games=[...new Set((Array.isArray(value.games)?value.games:[legacy[value.game]]).filter(id=>tcgCatalog.some(g=>g.id===id)))];
 const createdAt=typeof value.createdAt==='string'&&!Number.isNaN(Date.parse(value.createdAt))?value.createdAt:new Date().toISOString();
 const badgeIds=['first-match','same-rival-2','same-rival-3','same-rival-4'];
 const badges=[{id:'verso-welcome',earnedAt:value.badges?.find(b=>b.id==='verso-welcome')?.earnedAt||createdAt},...badgeIds.flatMap(id=>{const badge=value.badges?.find(item=>item.id===id);return badge?[{id,earnedAt:typeof badge.earnedAt==='string'?badge.earnedAt:createdAt}]:[];})];
 return {id:typeof value.id==='string'&&value.id?value.id:newLocalId(),name:value.name.trim().slice(0,40),mascot:value.mascot,games,background:profileBackgrounds.includes(value.background)?value.background:'aurora',backgroundImage:typeof value.backgroundImage==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value.backgroundImage)&&value.backgroundImage.length<700000?value.backgroundImage:'',createdAt,provider:'local',following:Array.isArray(value.following)?[...new Set(value.following.filter(id=>typeof id==='string'&&id&&id!==value.id))]:[],badges};
}
function loadProfiles(){
 const saved=store.read(profilesKey,[]),legacy=normalizeProfile(store.read(profileKey,null));
 const list=(Array.isArray(saved)?saved:[]).map(normalizeProfile).filter(Boolean);
 // The old single-profile key is imported once. It must never resurrect a deleted player.
 if(!Array.isArray(store.read(profilesKey,null))&&legacy)list.push(legacy);
 const unique=[...new Map(list.map(item=>[item.id,item])).values()];if(JSON.stringify(saved)!==JSON.stringify(unique))store.write(profilesKey,unique);return unique;
}
let profiles=loadProfiles(),localSession=store.read(sessionKey,null);
let profile=profiles.find(item=>item.id===localSession?.userId)||profiles[0]||null;
// Migrate existing previews without signing the player out.
if(profile&&!localSession){localSession={userId:profile.id,active:true};store.write(sessionKey,localSession);}
if(profile)store.write(profileKey,profile);
if(profile){const saved=store.read('verso-lorcana-saved-decks-v1',[]);if(Array.isArray(saved)&&saved.some(entry=>entry?.deck&&!entry.ownerId)){store.write('verso-lorcana-saved-decks-v1',saved.map(entry=>entry?.deck&&!entry.ownerId?{...entry,ownerId:profile.id}:entry));}}
function signedIn(){return Boolean(profile&&localSession?.active&&localSession.userId===profile.id);}
function saveProfile(next){const index=profiles.findIndex(item=>item.id===next.id),updated=profiles.slice(),previous=store.read(profileKey,null);if(index<0)updated.push(next);else updated[index]=next;if(!store.write(profilesKey,updated))return false;if(!store.write(profileKey,next)){store.write(profilesKey,profiles);if(previous)store.write(profileKey,previous);else store.remove(profileKey);return false;}profiles=updated;return true;}
function activateProfile(id=profile?.id){const next=profiles.find(item=>item.id===id);if(!next)return false;if(profile?.id!==next.id){const oldOwner=store.read('verso-lorcana-draft-owner-id',null),oldDraft=store.read('verso-lorcana-deck-v1',null);if(oldOwner===profile?.id&&oldDraft)store.write(`verso-lorcana-draft-${profile.id}`,oldDraft);store.remove('verso-lorcana-deck-v1');store.remove('verso-lorcana-active-deck-id');store.remove('verso-studio-open-request');store.remove('verso-studio-open-id');const nextDraft=store.read(`verso-lorcana-draft-${next.id}`,null);if(nextDraft)store.write('verso-lorcana-deck-v1',nextDraft);store.write('verso-lorcana-draft-owner-id',next.id);}profile=next;store.write(profileKey,profile);localSession={userId:profile.id,active:true};return store.write(sessionKey,localSession);}
function logout(){localSession={userId:profile?.id,active:false};store.write(sessionKey,localSession);navigate('login');notify('Logged out. Your local profile and decks are kept on this browser.');}
const navigation = [['feed','Feed'],['explore','Explore'],['new','New Post'],['decks','My Deck'],['profile','My Profile']];
for(const [target,mobile] of [['desktop-nav',false],['mobile-nav',true]]) document.getElementById(target).innerHTML=navigation.map(([page,label])=>`<button data-page="${page}" aria-label="${page==='new'?'Create a post':label}" title="${label}" ${page==='new'?`class="new-nav"${mobile?' aria-haspopup="dialog"':''}`:''}>${svg(page)}${mobile?'':`<span>${label}</span>`}</button>`).join('');
const mascot = (pose='hello',cls='',alt='TOMEO Spirit') => `<img class="mascot ${cls}" src="assets/verso-spirit-${pose}.webp" alt="${alt}" width="326" height="512">`;
const head=(eyebrow,title,copy,action='')=>`<div class="page-heading"><div>${eyebrow?`<p class="eyebrow">${eyebrow}</p>`:''}<h1>${title}</h1>${copy?`<p class="lead">${copy}</p>`:''}</div>${action}</div>`;
const empty=(icon,title,copy,action='')=>`<div class="empty-state">${svg(icon)}<h2>${title}</h2><p>${copy}</p>${action}</div>`;
function playerDeckEntries(ownerId=profile?.id,{publicOnly=false}={}){const saved=store.read('verso-lorcana-saved-decks-v1',[]);return Array.isArray(saved)?saved.filter(e=>e?.ownerId===ownerId&&e?.deck&&typeof e.deck.cards==='object'&&e.deck.cards!==null&&typeof e.id==='string'&&(!publicOnly||e.visibility==='public')):[];}
function deckEntries(){return playerDeckEntries(profile?.id);}
function visibleDeck(id){const saved=store.read('verso-lorcana-saved-decks-v1',[]);return Array.isArray(saved)?saved.find(entry=>entry?.id===id&&entry?.deck&&typeof entry.deck.cards==='object'&&(entry.ownerId===profile?.id||entry.visibility==='public')&&profiles.some(player=>player.id===entry.ownerId))||null:null;}
function deckVisibility(entry){return entry?.visibility==='public'?'public':'private';}
function updateDeckVisibility(id,visibility){if(!['public','private'].includes(visibility))return false;const saved=store.read('verso-lorcana-saved-decks-v1',[]);if(!Array.isArray(saved))return false;const entry=saved.find(item=>item?.id===id&&item.ownerId===profile?.id);if(!entry)return false;entry.visibility=visibility;entry.updatedAt=new Date().toISOString();return store.write('verso-lorcana-saved-decks-v1',saved);}
function deckCount(deck){return Object.values(deck.cards||{}).reduce((a,b)=>a+(Number.isFinite(b)?b:0),0);}
function deckCards(){const decks=deckEntries();if(!decks.length)return empty('decks','Your next deck starts here.','Choose a game, build in Deck Studio, then save it to your player profile.','<button class="primary" data-page="studio">Create your first deck '+svg('arrow')+'</button>');return `<div class="deck-grid">${decks.slice().reverse().map(entry=>`<article class="deck-tile">${deckCoverMarkup(entry,deckCardMap)}<div class="deck-tile-body"><small>DISNEY LORCANA · ${esc(profile?.name||'TOMEO PLAYER')} · ${deckVisibility(entry).toUpperCase()}</small><h2>${esc(entry.deck.name||'Untitled deck')}</h2><p>${deckCount(entry.deck)} cards · ${Object.keys(entry.deck.cards).length} unique</p><div class="deck-actions"><button class="secondary" data-view-deck-id="${esc(entry.id)}">View Deck ${svg('arrow')}</button><details class="deck-settings-menu"><summary aria-label="Deck settings" title="Deck settings">${svg('gear')}</summary><div><button data-action="rename-deck" data-deck-id="${esc(entry.id)}">Rename</button><button data-action="change-deck-cover" data-deck-id="${esc(entry.id)}">Change cover</button><button data-action="toggle-deck-visibility" data-deck-id="${esc(entry.id)}">Make ${deckVisibility(entry)==='public'?'private':'public'}</button><button data-action="edit-viewed-deck" data-deck-id="${esc(entry.id)}">Edit in Deck Studio</button><button class="danger-action" data-action="delete-deck" data-deck-id="${esc(entry.id)}">Delete Deck</button></div></details></div></div></article>`).join('')}</div>`;}
const pages = {
 welcome:()=>`<section class="landing"><div class="landing-copy"><p class="eyebrow">A HOME FOR TCG PLAYERS</p><h1>Discover.<br><em>Express.</em><br>Connect.</h1><p>Discover your world. Build your story. Meet your people.<br>TOMEO brings your cards, games, and community together.</p><div class="actions"><button class="primary" data-page="login">Start your story ${svg('arrow')}</button><a class="hero-link" href="#how-it-works" data-scroll="how-it-works">See how it works ↓</a></div><small>DISCOVER. EXPRESS. CONNECT.</small></div><div class="landing-art"><figure class="hero-mascot">${mascot('hello')}<figcaption>MEET YOUR NEW COMPANION</figcaption></figure><div class="floating-note"><span>✦</span><div><small>YOUR JOURNEY, TOGETHER</small><strong>Every game has a story.</strong></div></div></div></section>
 <section class="intro-section" id="how-it-works"><p class="eyebrow">MORE THAN A DECK LIST</p><h2>Your player identity,<br>built one game at a time.</h2><p>TOMEO is a TCG player platform for people who play, collect, and connect. Keep a personal profile, build decks, remember matches, and discover your local community.</p></section>
 <div class="feature-grid">${[['match','Play & remember','Keep match results and the moments around the table.'],['decks','Build & collect','Build in Deck Studio and keep your decks alongside your player story.'],['explore','Find your people','Discover friends, partner shops, and events around your favorite games.']].map(([i,t,c])=>`<article>${svg(i)}<h3>${t}</h3><p>${c}</p></article>`).join('')}</div>
 <section class="product-section"><div><p class="eyebrow">ONE PLAYER. ONE STORY.</p><h2>A profile that<br>grows with you.</h2><p>Badges mark your milestones. Decks show what you play. Match history and photos keep your memories close.</p><button class="secondary" data-page="setup">Preview a player profile ${svg('arrow')}</button></div><div class="profile-preview"><div class="preview-player">${mascot('win')}<div><small>EXAMPLE PROFILE</small><strong>Your player name</strong><span>Lorcana · Pokémon · One Piece</span></div></div><div class="preview-stats"><span><b>✦</b>Badges</span><span><b>▤</b>Decks</span><span><b>VS</b>Matches</span></div><div class="preview-album">${mascot('hold-card')}<div><small>YOUR MOMENTS</small><strong>The story behind<br>every card.</strong></div></div></div></section>
 <section class="studio-promo"><div><p class="eyebrow">START BUILDING TODAY</p><h2>Meet TOMEO Deck Studio.</h2><p>Browse the Lorcana card library, build your list, and save it to your local deck collection. Pokémon and One Piece are coming later.</p><button class="primary" data-page="studio">Explore Deck Studio ${svg('arrow')}</button></div><div class="card-stack" aria-hidden="true"><i></i><i></i><i>${svg('decks')}<span>TOMEO<br>DECK STUDIO</span></i></div></section>
 <section class="steps-section"><p class="eyebrow">YOUR FIRST STEPS</p><h2>From first hello to your next game.</h2><ol><li><b>01</b><h3>Make it yours</h3><p>Choose your name, games, and TOMEO Spirit.</p></li><li><b>02</b><h3>Build a deck</h3><p>Choose Lorcana and prepare your next list.</p></li><li><b>03</b><h3>Grow your story</h3><p>Record matches, share moments, and earn your first match badges.</p></li></ol></section>
 <section class="faq"><p class="eyebrow">GOOD TO KNOW</p><h2>Before you join.</h2><details><summary>What can I try today?</summary><p>Local player profiles, Lorcana Deck Studio, match records, and follower-only posts work on this device. Event registration and Google accounts are still being built.</p></details><details><summary>Are my decks saved to an account?</summary><p>Today they are saved in this browser. TOMEO and Deck Studio share the same local library when opened from the same website. Cloud accounts and cross-device syncing will come with Google sign-in.</p></details><details><summary>Can I use TOMEO on my phone?</summary><p>The player platform is designed for mobile use, with quick access to your profile and decks. Deck Studio also includes mobile card search and deck views.</p></details></section><footer class="site-footer"><strong>TOMEO</strong><span>DISCOVER. EXPRESS. CONNECT.</span><button class="text-link" data-page="login">Join the journey →</button></footer>`,
 feed:()=>renderFeedPage(),
 explore:()=>head('','Explore','')+`<div class="welcome-card explore-banner"><div><p class="eyebrow">YOUR LOCAL TCG COMMUNITY</p><h2>Great games start with good company.</h2><p>Shop pages, tournaments, and community activities are coming in the next release.</p></div><figure>${mascot('peek')}</figure></div>`+empty('explore','More places to play are coming.','Event discovery and registration are being built. No registrations are available in this preview.'),
 new:()=>location.hash==='#new'?renderNewPostChooserPage():renderNewPostPage(),
 decks:()=>`<div class="my-decks-page">${head('','My Deck','','<button class="primary" data-page="studio">'+svg('new')+'Create a deck</button>')}${deckCards()}</div>`,
 studio:()=>`<div class="studio-entry">${signedIn()?'<button class="back-link studio-mobile-back" data-page="decks">← My Deck</button>':''}<header class="studio-entry-heading"><p class="eyebrow">CHOOSE YOUR WORLD</p><h1>TOMEO<br><em>Deck Studio.</em></h1><p>A little inspiration. A whole new deck.<br>Choose your game and make it yours.</p><div class="studio-heading-orbit" aria-hidden="true">${svg('decks')}<span>PLAY YOUR WAY</span></div></header><div class="studio-portals"><button class="studio-portal lorcana-portal" data-page="lorcana"><div class="portal-copy"><span class="portal-status"><i></i> YOUR STUDIO IS READY</span><span class="portal-chapter">01 / THE WORLD OF INK</span><h2>Disney<br> Lorcana</h2><p>Find your inks. Bring your characters together.<br>Build something unexpected.</p><span class="portal-cta">Enter Lorcana Studio ${svg('arrow')}</span><span class="portal-detail">Card library · Deck builder · Your saved decks</span></div><div class="portal-scene" aria-hidden="true"><div class="ink-halo"></div><div class="ink-orbit"></div><img class="portal-card card-left" src="assets/studio-mickey.webp" alt="" width="367" height="512"><img class="portal-card card-right" src="assets/studio-stitch.webp" alt="" width="367" height="512"><img class="portal-card card-center" src="assets/studio-elsa.webp" alt="" width="367" height="512"><div class="portal-ink-dots"><i></i><i></i><i></i><i></i><i></i><i></i></div><span class="portal-spark spark-one">✦</span><span class="portal-spark spark-two">✦</span></div></button><div class="upcoming-portals">${[['02','Pokémon','A new adventure is taking shape.'],['03','One Piece','Your next voyage is on the horizon.']].map(([n,name,copy])=>`<div class="upcoming-portal" aria-disabled="true"><div class="upcoming-portal-art" aria-hidden="true">${svg('decks')}</div><span class="portal-chapter">${n} / COMING SOON</span><h2>${name}</h2><p>${copy}</p><span class="upcoming-status">STUDIO IN THE MAKING</span></div>`).join('')}</div></div><p class="studio-entry-footer">EVERY DECK IS THE START OF A STORY.</p></div>`,
 lorcana:()=>`<div class="studio-loading" id="studio-loading" role="status"><span class="eyebrow">ENTER YOUR CREATIVE SPACE</span><h1>TOMEO<br><em>Deck Studio.</em></h1><p id="studio-loading-copy">Preparing your Lorcana workspace…</p><span class="studio-loading-progress"></span><button class="secondary" data-page="decks">← My Deck</button></div><iframe id="studio-frame" src="${studioDistPath}/index.html?platform=1#builder" title="Lorcana Deck Studio" allow="clipboard-write"></iframe>`,

};
function gameTags(){return `<div class="game-tags">${(profile?.games||[]).map(id=>`<span>${esc(tcgCatalog.find(g=>g.id===id)?.name||id)}</span>`).join('')}</div>`;}
function welcomeBadgeArt(cls=''){return `<div class="welcome-badge-art ${cls}" aria-hidden="true"><div class="badge-seal">✦</div><span>TOMEO</span><strong>WELCOME</strong><small>YOUR STORY STARTS HERE</small></div>`;}
function backgroundPicker(chosen){const current=chosen.background||'aurora';return `<fieldset class="background-field"><legend>Profile background</legend><p class="field-help">Choose a look for your player card, or use your own image.</p><div class="background-options">${[['aurora','Aurora'],['midnight','Midnight'],['sunset','Sunset'],['mint','Mint'],['custom','Your photo']].map(([id,label])=>`<button type="button" class="background-option bg-${id} ${current===id?'selected':''}" data-background="${id}" aria-pressed="${current===id}"><span class="background-swatch"></span><strong>${label}</strong></button>`).join('')}</div><label class="background-upload ${current==='custom'?'':'is-hidden'}" for="background-file">Upload a background photo <span>JPG, PNG or WebP · saved on this device</span></label><input class="background-file ${current==='custom'?'':'is-hidden'}" id="background-file" type="file" accept="image/jpeg,image/png,image/webp"><p id="background-status" class="field-help" role="status">${current==='custom'&&chosen.backgroundImage?'Current photo is saved to this profile.':''}</p></fieldset>`;}
function playerForm(edit=false,subject=profile){const chosen=subject||{mascot:'hello',games:[]};return `<form id="setup-form" class="setup-card" data-mode="${edit?'edit':'new'}"><label for="player-name">Player name</label><input id="player-name" name="name" required maxlength="40" autocomplete="nickname" placeholder="What should we call you?" value="${esc(chosen.name||'')}"><fieldset><legend>Choose your TOMEO Spirit</legend><div class="mascot-options">${['hello','win','peek'].map((pose,i)=>`<button type="button" class="mascot-option ${pose===(chosen.mascot||'hello')?'selected':''}" data-mascot="${pose}" aria-pressed="${pose===(chosen.mascot||'hello')}" aria-label="Choose ${['Hello','Celebrate','Curious'][i]} Spirit">${mascot(pose,'','')}<span>${['Hello','Celebrate','Curious'][i]}</span></button>`).join('')}</div></fieldset>${backgroundPicker(chosen)}<fieldset><legend>Your TCGs</legend><p class="field-help">Choose all the games you play or collect. You can change these later.</p><div class="game-picker">${tcgCatalog.map(g=>`<label class="game-option"><input type="checkbox" name="games" value="${g.id}" ${(chosen.games||[]).includes(g.id)?'checked':''}><span>${esc(g.name)}</span></label>`).join('')}</div></fieldset><p id="setup-error" class="form-error" role="alert" tabindex="-1"></p><button class="primary full" type="submit">${edit?'Save changes':'Create local profile'} ${svg('arrow')}</button><p class="muted">This profile stays in this browser. You can keep multiple local profiles and switch between them.</p></form>`;}
function localProfileChoices(){return profiles.length?`<div class="local-profile-list">${profiles.map(item=>`<button data-profile-id="${esc(item.id)}"><img src="assets/verso-spirit-${item.mascot}.webp" alt=""><span><strong>${esc(item.name)}</strong><small>${item.games.length} game${item.games.length===1?'':'s'} · Local profile</small></span>${svg('arrow')}</button>`).join('')}</div><button class="secondary full" data-page="new-profile">＋ Add another local profile</button>`:`<p>Create your player profile first. Choose a name, a Spirit, and your favorite games.</p><button class="primary full" data-page="setup">Create my profile ${svg('arrow')}</button>`;}
pages.setup=()=>head('MAKE IT YOURS',profile?'Edit your player identity.':'Your player identity.','Pick a name, your Spirit, and all the games you love.')+playerForm(Boolean(profile));
pages['new-profile']=()=>`<button class="back-link" data-page="login">← Local profiles</button>`+head('NEW PLAYER','Create another profile.','Each local player keeps a separate identity and deck library on this browser.')+playerForm(false,null);
pages.settings=()=>head('','Settings','')+`<div class="settings-layout">${playerForm(true)}<aside class="settings-info"><section><p class="eyebrow">PLAYER ID</p><h2>One identity for your journey.</h2><p>Your name and games can change. Your local player ID stays the same.</p><code>${esc(profile?.id)}</code><span class="pill">LOCAL PROFILE</span></section><section><p class="eyebrow">GOOGLE ACCOUNT</p><h2>Link when you’re ready.</h2><p>Google linking is not connected yet. The intended flow keeps this player identity, decks, and badges when you link.</p><button class="google-button" disabled>Link Google account · Coming soon</button></section><section><h2>Appearance</h2><p>Your theme is shared with Deck Studio.</p><button class="secondary" data-action="toggle-theme">Toggle Light / Night</button></section><section class="danger-zone"><p class="eyebrow">DELETE PROFILE</p><h2>Delete this local profile.</h2><p>This permanently removes ${esc(profile?.name)}, their decks, drafts, posts, matches and photos stored in this browser. Nothing transfers to another profile.</p><button class="secondary danger-button" data-action="delete-profile">Delete account profile</button></section></aside></div>`;
pages.login=()=>`<section class="auth-layout"><div class="auth-art"><p class="eyebrow">YOUR STORY STARTS HERE</p><h1>Play. Collect.<br>Connect.</h1><p>A home for the games you play and the people you play them with.</p><figure>${mascot('peek')}</figure></div><div class="auth-card"><button class="back-link" data-page="welcome">← About TOMEO</button><p class="eyebrow">LOCAL PLAYERS</p><h2>${profiles.length?'Who’s playing?':'Start your player story.'}</h2>${localProfileChoices()}<hr><button class="google-button" disabled aria-describedby="auth-note"><b aria-hidden="true">G</b>Continue with Google</button><p id="auth-note" class="notice">Google sign-in and linking are coming later. Local profiles work without Google.</p></div></section>`;
pages.profile=()=>renderProfilePage();
pages.player=()=>renderPlayerPage();
pages['post-story']=()=>renderPostStoryPage();
let searchQuery='',searchType='all';
pages.search=()=>renderSearchPage();
pages['profile-qr']=()=>renderProfileQrPage();
pages['profile-story']=()=>`<button class="back-link" data-page="profile">← My Profile</button>`+head('','Share Profile','')+`<div class="story-layout"><div class="story-preview"><canvas id="profile-story-canvas" width="1080" height="1920" role="img" aria-label="Profile Story graphic for ${esc(profile?.name)}"></canvas></div><div class="story-actions"><span class="pill">LOCAL PLAYER PROFILE</span><h2>Your player card</h2><p>Save or share your TOMEO player card. This local preview has no public profile link yet.</p><button class="primary full" data-action="download-profile-story">Download profile image ${svg('arrow')}</button><button class="secondary full" data-action="share-profile-story">Share image</button>${instagramStoryButton('profile')}<p class="muted">1080 × 1920 · Share to your Story or save the image.</p></div></div>`;
pages.badges=()=>`<button class="back-link" data-page="profile">← My Profile</button>`+head('','My Badges','')+`<div class="badge-grid"><button class="badge-collection-item" data-page="welcome-badge">${welcomeBadgeArt()}<span class="pill">UNLOCKED</span><h2>TOMEO Welcome</h2><p>Created your player profile.</p></button>${(profile?.badges||[]).filter(badge=>matchBadgeDetails[badge.id]).map(badge=>`<article class="badge-collection-item match-badge-item">${svg('badge')}<span class="pill">EARNED ${esc(postDate(badge.earnedAt))}</span><h2>${esc(matchBadgeDetails[badge.id].title)}</h2><p>${esc(matchBadgeDetails[badge.id].description)}</p></article>`).join('')}</div><p class="muted">Earned badges stay in your collection, even if a Match post is removed.</p>${(profile?.badges||[]).length===1?'<p class="muted">Record a match to earn your next badge.</p>':''}`;
pages['welcome-badge']=()=>`<button class="back-link" data-page="profile">← My Profile</button>`+head('YOUR FIRST MILESTONE','TOMEO Welcome','Your story starts here. Make it a moment worth sharing.')+`<div class="story-layout"><div class="story-preview"><canvas id="story-canvas" width="1080" height="1920" role="img" aria-label="TOMEO Welcome badge Story graphic for ${esc(profile?.name)}"></canvas></div><div class="story-actions"><span class="pill">UNLOCKED</span><h2>Welcome to the table.</h2><p>Your player name, game tags, and first TOMEO badge, together in one Story graphic.</p><button class="primary full" data-action="download-story">Download Story PNG ${svg('arrow')}</button><button class="secondary full" data-action="share-story">Share image</button>${instagramStoryButton('badge')}<p class="muted">1080 × 1920 · Save the image and add it to your Instagram Story. “Share image” opens your device’s share menu when supported.</p></div></div>`;
let viewingDeckId='',deckCardMap=null,deckCatalogError='';
pages.deck=()=>{const entry=visibleDeck(viewingDeckId);if(!entry)return `<button class="back-link" data-page="decks">← My Deck</button>`+empty('decks','Deck not found','This deck is private or no longer available.');const owner=profiles.find(item=>item.id===entry.ownerId),mine=entry.ownerId===profile?.id;if(deckCatalogError)return `<button class="back-link" data-page="${mine?'decks':'player/'+encodeURIComponent(entry.ownerId)}">← Back</button>`+empty('decks','Card library unavailable',deckCatalogError,'<button class="secondary" data-action="retry-deck-catalog">Try again</button>');if(!deckCardMap)return `<button class="back-link" data-page="${mine?'decks':'player/'+encodeURIComponent(entry.ownerId)}">← ${esc(mine?'My Deck':owner?.name||'Player Profile')}</button>`+empty('decks','Preparing your deck preview','Loading card artwork and deck details…');return deckPreviewMarkup(entry,deckCardMap,{ownerName:owner?.name||'TOMEO Player',canEdit:mine,backPage:mine?'decks':'player/'+encodeURIComponent(entry.ownerId),backLabel:mine?'My Deck':owner?.name||'Player Profile'});};
pages['deck-story']=()=>{const entry=visibleDeck(viewingDeckId);if(!entry)return `<button class="back-link" data-page="decks">← My Deck</button>`+empty('decks','Deck not found','This deck is private or no longer available.');return `<button class="back-link" data-view-deck-id="${esc(entry.id)}">← Deck Preview</button>`+head('','Share Deck','')+`<div class="story-layout"><div class="story-preview"><canvas id="deck-story-canvas" width="1080" height="1920" role="img" aria-label="Story graphic for ${esc(entry.deck.name||'Untitled deck')}"></canvas></div><div class="story-actions"><span class="pill">DISNEY LORCANA</span><h2>${esc(entry.deck.name||'Untitled deck')}</h2><p>A 1080 × 1920 deck graphic using this deck’s cover and color theme.</p><button class="primary full" data-action="download-deck-story">Download Story PNG ${svg('arrow')}</button><button class="secondary full" data-action="share-deck-story-image">${svg('share')} Share image</button>${instagramStoryButton('deck')}<p class="muted">On supported phones, Share image opens the system share menu so you can choose Instagram Stories.</p></div></div>`;};
async function loadDeckCatalog(){if(deckCardMap||loadDeckCatalog.pending)return;loadDeckCatalog.pending=true;try{const response=await fetch(`${studioDistPath}/data/cards.json`);if(!response.ok)throw Error('Could not load the Lorcana card library.');const cards=await response.json();if(!Array.isArray(cards))throw Error('The card library is unavailable.');deckCardMap=new Map(cards.map(card=>[card.id,card]));deckCatalogError='';}catch(error){deckCatalogError=error.message||'Please try again.';}finally{loadDeckCatalog.pending=false;if(['deck','deck-story','profile','decks'].includes(currentPage))render();}}
let currentPage='';
let backgroundUpload='';
function themeValue(){try{return localStorage.getItem('verso-theme')||localStorage.getItem('verso-lorcana-theme')||'light';}catch{return 'light';}}
function applyTheme(value){const theme=value==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('verso-theme',theme);localStorage.setItem('verso-lorcana-theme',theme);}catch{}document.getElementById('brand-logo').src=`assets/tomeo-logo-horizontal${theme==='dark'?'-dark':''}.svg`;const toggle=document.getElementById('theme-toggle');toggle.innerHTML=svg(theme==='dark'?'sun':'moon');toggle.setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'night'} mode`);toggle.title=toggle.getAttribute('aria-label');document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#121634':'#f7f7fc';document.getElementById('studio-frame')?.contentWindow?.postMessage({type:'verso-theme',theme},location.origin==='null'?'*':location.origin);}
function render(){
 const hash=location.hash.slice(1);
 let page=Object.hasOwn(pages,hash)?hash:(signedIn()?'feed':'welcome');
 if(hash==='new/match'||hash==='new/moment'){page='new';composeMode=hash.slice(4);}
 if(hash.startsWith('deck/')){page='deck';try{viewingDeckId=decodeURIComponent(hash.slice(5));}catch{viewingDeckId='';}}
 if(hash.startsWith('deck-story/')){page='deck-story';try{viewingDeckId=decodeURIComponent(hash.slice(11));}catch{viewingDeckId='';}}
 if(hash.startsWith('player/')){page='player';try{viewingPlayerId=decodeURIComponent(hash.slice(7));}catch{viewingPlayerId='';}}
 if(hash.startsWith('post-story/')){page='post-story';try{viewingPostId=decodeURIComponent(hash.slice(11));}catch{viewingPostId='';}}
 const privatePages=['feed','explore','new','search','decks','deck','deck-story','lorcana','profile','player','post-story','profile-story','profile-qr','settings','badges','welcome-badge'];
 if(!signedIn()&&(privatePages.includes(page)||(page==='setup'&&profile)))page='login';
 clearTimeout(render.studioTimeout);
 clearTimeout(render.studioReveal);render.studioStarted=Date.now();
 currentPage=page;
 if(['settings','setup','new-profile'].includes(page))backgroundUpload='';
 const view=document.getElementById('view');view.innerHTML=pages[page]();
if(['deck','deck-story'].includes(page)&&!deckCardMap&&!deckCatalogError&&visibleDeck(viewingDeckId))loadDeckCatalog();
 document.body.classList.toggle('public-page',['welcome','login','setup','new-profile'].includes(page));
 document.body.classList.toggle('signed-in',signedIn());
 document.body.classList.toggle('studio-page',page==='lorcana');
 if(page==='lorcana')render.studioTimeout=setTimeout(()=>{const copy=document.getElementById('studio-loading-copy');if(copy)copy.textContent='Studio is taking longer to load. Check that the local preview server is running, then return to My Deck and try again.';},15000);
 document.getElementById('home-link').href=signedIn()?'#feed':'#welcome';
 document.getElementById('account-menu').open=false;
 document.getElementById('account-name').textContent=profile?.name||'TOMEO Player';
 const searchInput=document.getElementById('global-search-input');if(searchInput&&searchInput.value!==searchQuery)searchInput.value=searchQuery;
 document.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===page||(['studio','lorcana','deck'].includes(page)&&b.dataset.page==='decks')||(['settings','badges','welcome-badge','profile-story','profile-qr'].includes(page)&&b.dataset.page==='profile');b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 document.getElementById('account-avatar').src=`assets/verso-spirit-${profile?.mascot||'hello'}.webp`;
 const titles={welcome:'Your TCG story',login:'Choose local profile',setup:'Player setup','new-profile':'New local profile',settings:'Settings',badges:'My Badges','welcome-badge':'TOMEO Welcome','profile-story':'Share Profile','profile-qr':'Profile QR',decks:'My Deck',deck:'Deck Preview','deck-story':'Share Deck',studio:'Deck Studio',lorcana:'Lorcana Deck Studio',profile:'My Profile',player:'Player Profile','post-story':'Share Post',feed:'Feed',explore:'Explore',new:hash==='new/match'?'Record Match':hash==='new/moment'?'Post a Moment':'New Post',search:'Search'};
 document.title=`${titles[page]} · TOMEO`;
 if(page==='welcome-badge')drawWelcomeStory(document.getElementById('story-canvas'),profile);
 if(page==='profile-story')drawProfileStory(document.getElementById('profile-story-canvas'),profile,deckEntries().length,playerMatchStats(profile?.id).matches);
 if(page==='post-story'){const post=postList().find(item=>item.id===viewingPostId);if(post&&canViewPost(post))drawPostStory(document.getElementById('post-story-canvas'),post,profiles.find(item=>item.id===post.ownerId));}
if(page==='deck-story'&&deckCardMap){const entry=visibleDeck(viewingDeckId);if(entry)drawDeckStory(document.getElementById('deck-story-canvas'),entry,deckCardMap,profiles.find(item=>item.id===entry.ownerId)?.name||'TOMEO Player');}
 window.scrollTo(0,0);view.focus({preventScroll:true});
}
function notify(text){const status=document.getElementById('status');status.textContent=text;status.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>status.classList.remove('visible'),4500);}
function askUser({title,message,confirmLabel='Continue',danger=false,inputValue=null}){
 const dialog=document.getElementById('verso-dialog'),field=document.getElementById('verso-dialog-field'),input=document.getElementById('verso-dialog-input');
 if(dialog.open)dialog.close('cancel');
 document.getElementById('verso-dialog-title').textContent=title;
 document.getElementById('verso-dialog-message').textContent=message;
 document.getElementById('verso-dialog-confirm').textContent=confirmLabel;
 dialog.querySelector('[value="cancel"]').onclick=()=>dialog.close('cancel');
 dialog.classList.toggle('verso-dialog-danger',danger);
 field.hidden=inputValue===null;
 if(inputValue!==null)input.value=inputValue;
 return new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'?(inputValue===null?true:input.value):null),{once:true});dialog.showModal();if(inputValue!==null)input.focus();});
}
function navigate(page){if(location.hash===`#${page}`)render();else location.hash=page;}
async function renameDeck(id){const list=store.read('verso-lorcana-saved-decks-v1',[]),entry=Array.isArray(list)?list.find(item=>item?.id===id&&item.ownerId===profile?.id):null;if(!entry)return;const name=await askUser({title:'Rename deck',message:'Choose a name for this deck.',confirmLabel:'Save name',inputValue:entry.deck.name||'Untitled deck'});if(name===null)return;const clean=name.trim().slice(0,100);if(!clean){notify('Please enter a deck name.');return;}entry.deck.name=clean;entry.updatedAt=new Date().toISOString();store.write('verso-lorcana-saved-decks-v1',list);try{if(localStorage.getItem('verso-lorcana-active-deck-id')===id){const draft=store.read('verso-lorcana-deck-v1',null);if(draft){draft.name=clean;store.write('verso-lorcana-deck-v1',draft);}}}catch{}render();notify('Deck renamed.');}
async function deleteDeck(id){const entry=deckEntries().find(item=>item.id===id);if(!entry||!await askUser({title:'Delete this deck?',message:`“${entry.deck.name||'Untitled deck'}” will be permanently removed from your profile.`,confirmLabel:'Delete deck',danger:true}))return;const list=store.read('verso-lorcana-saved-decks-v1',[]);store.write('verso-lorcana-saved-decks-v1',Array.isArray(list)?list.filter(item=>item?.id!==id):[]);removeDeckAppearance(id);try{if(localStorage.getItem('verso-lorcana-active-deck-id')===id){store.remove('verso-lorcana-active-deck-id');store.remove('verso-lorcana-deck-v1');}}catch{}render();notify('Deck deleted.');}
function openDeckEditor(id,{cardId=''}={}){const entry=deckEntries().find(item=>item.id===id);if(!entry)return;if(cardId)store.write('verso-studio-detail-card-id',cardId);else{store.remove('verso-studio-detail-card-id');store.remove('verso-studio-detail-card-name');}store.write('verso-studio-open-request',entry.deck);store.write('verso-studio-open-id',entry.id);navigate('lorcana');}
function requestDeckCoverUpload(id){if(!deckEntries().some(item=>item.id===id))return;document.getElementById('deck-cover-file')?.remove();const input=document.createElement('input');input.type='file';input.id='deck-cover-file';input.accept='image/jpeg,image/png,image/webp';input.dataset.deckId=id;input.hidden=true;document.body.append(input);input.click();}
async function openCardDetailInStudio(deckId,cardId){const entry=visibleDeck(deckId);if(!entry||!entry.deck.cards[cardId])return;if(!await askUser({title:'View card in Deck Studio?',message:'You’ll open the details for this card in Lorcana Deck Studio.',confirmLabel:'Open card'}))return;if(entry.ownerId===profile?.id)openDeckEditor(deckId,{cardId});else{store.write('verso-studio-detail-card-id',cardId);store.write('verso-studio-open-request',{name:'Untitled deck',cards:{},settings:{mode:'constructed',inks:[]}});store.remove('verso-studio-open-id');navigate('lorcana');}}
const playerCollections=['verso-player-posts-v1','verso-player-matches-v1','verso-player-photos-v1','verso-player-events-v1','verso-player-shops-v1'];
const belongsToPlayer=(item,id)=>item?.ownerId===id||item?.userId===id||item?.profileId===id;
async function deleteProfile(){if(!profile)return;const deletedId=profile.id,owned=deckEntries().length;const related=playerCollections.reduce((count,key)=>{const items=store.read(key,[]);return count+(Array.isArray(items)?items.filter(item=>belongsToPlayer(item,deletedId)).length:0);},0);if(!await askUser({title:'Delete this profile?',message:`“${profile.name}”, ${owned} deck${owned===1?'':'s'} and ${related} other item${related===1?'':'s'} will be permanently removed from this browser.`,confirmLabel:'Delete profile',danger:true}))return;
 const decks=store.read('verso-lorcana-saved-decks-v1',[]);if(Array.isArray(decks)){decks.filter(entry=>entry?.ownerId===deletedId).forEach(entry=>removeDeckAppearance(entry.id));store.write('verso-lorcana-saved-decks-v1',decks.filter(entry=>entry?.ownerId!==deletedId));}
 for(const key of playerCollections){const items=store.read(key,[]);if(Array.isArray(items))store.write(key,items.filter(item=>!belongsToPlayer(item,deletedId)));}
 store.remove(`verso-lorcana-draft-${deletedId}`);store.remove('verso-lorcana-draft-owner-id');store.remove('verso-lorcana-deck-v1');store.remove('verso-lorcana-active-deck-id');store.remove('verso-studio-open-id');store.remove('verso-studio-open-request');
 cleanupDeletedProfileReferences(deletedId);
 profiles=profiles.filter(item=>item.id!==deletedId).map(item=>({...item,following:followingIds(item).filter(id=>id!==deletedId)}));store.write(profilesKey,profiles);profile=profiles[0]||null;if(profile)store.write(profileKey,profile);else store.remove(profileKey);localSession={userId:profile?.id||null,active:false};store.write(sessionKey,localSession);navigate('login');notify('Local profile and linked data deleted.');}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action]');
 const searchTab=event.target.closest('[data-search-type]');if(searchTab){searchType=searchTab.dataset.searchType;updateSearchResults();return;}
 if(action?.dataset.action==='toggle-theme'){applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');return;}
 if(action?.dataset.action==='rename-deck'){renameDeck(action.dataset.deckId);return;}
 if(action?.dataset.action==='change-deck-cover'){requestDeckCoverUpload(action.dataset.deckId);return;}
 if(action?.dataset.action==='toggle-deck-visibility'){const entry=deckEntries().find(item=>item.id===action.dataset.deckId);if(entry&&updateDeckVisibility(entry.id,deckVisibility(entry)==='public'?'private':'public')){render();notify(`Deck is now ${deckVisibility(visibleDeck(entry.id))}.`);}else notify('Could not update deck visibility.');return;}
 if(action?.dataset.action==='remove-deck-cover'){if(deckEntries().some(item=>item.id===action.dataset.deckId)&&setDeckAppearance(action.dataset.deckId,{coverImage:''})){render();notify('Deck cover image removed.');}return;}
 if(action?.dataset.action==='set-deck-theme'){if(deckEntries().some(item=>item.id===action.dataset.deckId)&&deckThemes[action.dataset.theme]){setDeckAppearance(action.dataset.deckId,{theme:action.dataset.theme});render();notify('Deck theme updated.');}return;}
 if(action?.dataset.action==='delete-deck'){deleteDeck(action.dataset.deckId);return;}
 if(action?.dataset.action==='delete-profile'){deleteProfile();return;}
 if(action?.dataset.action==='switch-profile'){localSession={userId:profile?.id||null,active:false};store.write(sessionKey,localSession);navigate('login');return;}
 if(action?.dataset.action==='logout'){logout();return;}
 if(action?.dataset.action==='resume'){if(profile){activateProfile();navigate('feed');}return;}
 if(action?.dataset.action==='download-story'){downloadWelcomeStory().catch(()=>notify('Could not export the image. Please try again.'));return;}
 if(action?.dataset.action==='share-story'){shareWelcomeStory().catch(()=>notify('Could not share the image. Try Download Story instead.'));return;}
 if(action?.dataset.action==='download-profile-story'){downloadProfileStory().catch(()=>notify('Could not export the image. Please try again.'));return;}
 if(action?.dataset.action==='share-profile-story'){shareProfileStory().catch(()=>notify('Could not share the image. Try Download Story instead.'));return;}
 if(action?.dataset.action==='publish-instagram-story'){publishStoryFromPage(action.dataset.storyKind).catch(error=>notify(error.message||'Could not publish Instagram Story.'));return;}
 if(action?.dataset.action==='edit-viewed-deck'){openDeckEditor(action.dataset.deckId);return;}
 if(action?.dataset.action==='view-card-detail'){openCardDetailInStudio(action.dataset.deckId,action.dataset.cardId);return;}
 if(action?.dataset.action==='share-deck-story'){navigate('deck-story/'+encodeURIComponent(action.dataset.deckId));return;}
 if(action?.dataset.action==='download-deck-story'){downloadDeckStory().catch(()=>notify('Could not export the Story image. Please try again.'));return;}
 if(action?.dataset.action==='share-deck-story-image'){shareDeckStory().catch(()=>notify('Could not share the Story image. Try Download instead.'));return;}
 if(action?.dataset.action==='retry-deck-catalog'){deckCatalogError='';loadDeckCatalog();render();return;}
 const menu=document.getElementById('account-menu');if(!menu.contains(event.target))menu.open=false;const activeDeckMenu=event.target.closest('.deck-settings-menu');document.querySelectorAll('.deck-settings-menu[open]').forEach(details=>{if(details!==activeDeckMenu)details.open=false;});
 const backgroundButton=event.target.closest('[data-background]');if(backgroundButton){const selected=backgroundButton.dataset.background;document.querySelectorAll('[data-background]').forEach(button=>{button.classList.toggle('selected',button===backgroundButton);button.setAttribute('aria-pressed',String(button===backgroundButton));});document.querySelector('.background-upload')?.classList.toggle('is-hidden',selected!=='custom');document.querySelector('.background-file')?.classList.toggle('is-hidden',selected!=='custom');return;}
 const viewDeckButton=event.target.closest('[data-view-deck-id]');if(viewDeckButton){navigate('deck/'+encodeURIComponent(viewDeckButton.dataset.viewDeckId));return;}const profileButton=event.target.closest('[data-profile-id]');if(profileButton){if(activateProfile(profileButton.dataset.profileId)){navigate('feed');notify(`Welcome back, ${profile.name}.`);}return;}
 const mascotButton=event.target.closest('[data-mascot]');if(mascotButton){document.querySelectorAll('[data-mascot]').forEach(b=>{b.classList.toggle('selected',b===mascotButton);b.setAttribute('aria-pressed',String(b===mascotButton));});return;}const deckButton=event.target.closest('[data-deck-id]');if(deckButton){openDeckEditor(deckButton.dataset.deckId);return;}const scroll=event.target.closest('[data-scroll]');if(scroll){event.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const page=event.target.closest('[data-page]');if(page){if(page.dataset.page==='new'){if(page.closest('#mobile-nav'))openPostChooser();else{if(currentPage!=='new')composeReturnPage=location.hash.slice(1)||'feed';navigate('new');}return;}if(page.dataset.page==='studio'){store.write('verso-studio-open-request',{name:'Untitled deck',cards:{},settings:{mode:'constructed',inks:[]}});store.remove('verso-studio-open-id');store.remove('verso-lorcana-active-deck-id');}navigate(page.dataset.page);}});
document.addEventListener('submit',event=>{
 if(event.target.id!=='setup-form')return;event.preventDefault();
 const name=document.getElementById('player-name').value.trim();
 const games=Array.from(document.querySelectorAll('input[name="games"]:checked'),input=>input.value);
 const error=document.getElementById('setup-error');
 if(!name||!games.length){error.textContent=!name?'Please enter your player name.':'Choose at least one game.';error.focus();return;}
 const creating=event.target.dataset?.mode==='new'||!profile,previous=creating?null:profile;
 const background=document.querySelector('.background-option.selected')?.dataset?.background||'aurora';
 const backgroundImage=backgroundUpload||(!creating?profile?.backgroundImage:'')||'';
 if(background==='custom'&&!backgroundImage){error.textContent='Upload a background photo before choosing Your photo.';error.focus();return;}
 const next=normalizeProfile({...(!creating&&profile?profile:{}),name,mascot:document.querySelector('.mascot-option.selected').dataset.mascot,games,background,backgroundImage});
 if(!saveProfile(next)){error.textContent='Browser storage is unavailable. Enable storage to save your profile.';error.focus();return;}
 profile=next;const active=activateProfile(next.id);
 navigate('profile');notify(active?(previous?'Profile updated.':'Welcome to TOMEO! Your first badge is ready.'):'Profile saved, but this visit could not be remembered.');
});
document.getElementById('global-search').addEventListener('submit',event=>{event.preventDefault();searchQuery=document.getElementById('global-search-input').value.trim();searchType='all';navigate('search');});
document.getElementById('global-search-input').addEventListener('input',event=>{searchQuery=event.target.value;if(currentPage==='search')updateSearchResults();});
document.addEventListener('change',async event=>{if(event.target.id!=='deck-cover-file')return;const input=event.target,file=input.files?.[0],id=input.dataset.deckId;if(!file){input.remove();return;}if(!deckEntries().some(item=>item.id===id)||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12_000_000){notify('Choose a JPG, PNG or WebP image smaller than 12 MB.');input.remove();return;}const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const scale=Math.min(1,1200/image.width,900/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.75);if(data.length>=700000)throw Error('Image is too large after resizing. Try a smaller image.');if(!setDeckAppearance(id,{coverImage:data}))throw Error('Browser storage is full. Remove another image and try again.');render();notify('Deck cover updated.');}catch(error){notify(error.message||'Could not save this image.');}finally{URL.revokeObjectURL(url);input.remove();}});
document.addEventListener('change',async event=>{if(event.target.id!=='background-file')return;const file=event.target.files?.[0],status=document.getElementById('background-status'),submit=document.querySelector('#setup-form button[type="submit"]');if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12_000_000){status.textContent='Choose a JPG, PNG or WebP image smaller than 12 MB.';event.target.value='';return;}submit.disabled=true;status.textContent='Preparing your photo…';const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const scale=Math.min(1,1400/image.width,800/image.height),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.78);if(data.length>=700000)throw Error('Image is too large after resizing. Try a smaller photo.');backgroundUpload=data;status.textContent='Photo ready. Save changes to apply it.';}catch(error){status.textContent=error.message||'Could not read this photo.';event.target.value='';}finally{URL.revokeObjectURL(url);submit.disabled=false;}});
document.getElementById('theme-toggle').addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
window.addEventListener('message',event=>{const frame=document.getElementById('studio-frame');if(!frame||event.source!==frame.contentWindow||(location.origin!=='null'&&event.origin!==location.origin))return;if(event.data?.type==='verso-theme')applyTheme(event.data.theme);if(event.data?.type==='verso-return')navigate('decks');if(event.data?.type==='verso-studio-ready'){clearTimeout(render.studioTimeout);render.studioReveal=setTimeout(()=>document.getElementById('studio-loading')?.remove(),Math.max(0,650-(Date.now()-render.studioStarted)));}if(event.data?.type==='verso-studio-ready')frame.contentWindow.postMessage({type:'verso-context',theme:document.documentElement.dataset.theme,profile:signedIn()?profile:null},location.origin==='null'?'*':location.origin);});
window.addEventListener('storage',event=>{if(event.key==='verso-theme')applyTheme(event.newValue);if([profilesKey,profileKey,sessionKey].includes(event.key)){profiles=loadProfiles();localSession=store.read(sessionKey,null);profile=profiles.find(item=>item.id===localSession?.userId)||profiles[0]||null;render();}if(event.key==='verso-lorcana-saved-decks-v1'&&['decks','profile','player','deck','deck-story'].includes(currentPage))render();if([postsKey,matchesKey].includes(event.key)&&['feed','profile','player','badges','post-story'].includes(currentPage))render();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.getElementById('account-menu').open=false;});
window.addEventListener('hashchange',()=>{const dialog=document.getElementById('post-choice-dialog');if(dialog?.open&&location.hash!==composeDialogHash)dialog.close();render();});
